// Feature 43 on the ARM GCC build (real STM32Cube HAL) and the firmware emulator: a main.c generated by CubeMX with
// one .c/.h pair per peripheral — it only includes i2c.h / usart.h / gpio.h — builds as pasted, because the build writes
// the pairs from the Pinout settings, and prints the DS3231's seconds on USART2. Both boards; and the Pinout option on.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import {createRequire} from 'node:module';
import {FirmwareSession} from '../../src/firmware-session.js';
import {generateHal,validateMcu} from '../../src/mcu-config.js';
import {LECTURE_MAIN,lectureProject} from '../fixtures/lecture-ds3231.js';

const require=createRequire(import.meta.url),{prepareBuild,build,detectTools}=require('../../desktop/native-build.cjs');
const tools=await detectTools({armGcc:process.env.ARM_GCC||''});
const skip=!(tools.armGcc&&tools.cube&&tools.cubeF1)&&!process.env.CI_REQUIRE_TOOLCHAIN&&'ARM GCC / STM32CubeF4·F1 not installed';
const exists=file=>fs.access(file).then(()=>true,()=>false);

test('the lecture main.c builds as pasted and prints "N sec" from the DS3231 (F446RE and F103RB)',{skip,timeout:900000},async()=>{
 const root=await fs.mkdtemp(path.join(os.tmpdir(),'pairs-'));
 try{
  for(const board of ['nucleo-f446re','nucleo-f103rb']){
   const p=lectureProject(board);p.code=LECTURE_MAIN;
   const plan=await prepareBuild({project:p,tools,root,target:'arm'});
   for(const name of ['i2c.h','i2c.c','usart.h','usart.c','gpio.h','gpio.c'])assert.ok(await exists(path.join(plan.directory,name)),`${board}: ${name} is written`);
   const result=await build(plan);
   assert.deepEqual(result.diagnostics.filter(d=>d.severity==='error'),[],board);
   assert.deepEqual(result.diagnostics.filter(d=>d.severity==='warning'&&/^(i2c|usart|gpio)\.[ch]$/.test(d.file)),[],`${board}: the generated pairs compile without warnings`);
   const s=new FirmwareSession(p,{elf:new Uint8Array(await fs.readFile(result.elf))});
   for(let t=20;t<=2700;t+=20)s.tick(t);
   const seconds=[...(s.buses.vcpOutput||'').matchAll(/(\d+) sec\r\n/g)].map(m=>Number(m[1]));
   assert.ok(seconds.length>=4,`${board}: ${JSON.stringify(s.buses.vcpOutput)}`);
   assert.ok(seconds.every(n=>n>=0&&n<60)&&new Set(seconds).size>=2,`${board}: the seconds run on: ${seconds.join(',')}`);
  }
 }finally{await fs.rm(root,{recursive:true,force:true});}
});

test('the Pinout option on: the generated main.c and its pairs build and run (I2C, USART, ADC, a PWM timer)',{skip,timeout:900000},async()=>{
 const root=await fs.mkdtemp(path.join(os.tmpdir(),'pairs-'));
 try{
  const pin=fn=>({function:fn,pull:'NOPULL',edge:'FALLING',label:'',initial:0});
  for(const board of ['nucleo-f446re','nucleo-f103rb']){
   const p=lectureProject(board);
   Object.assign(p.mcu.pins,{PA0:pin('ADC1_IN0'),PA6:pin('TIM3_CH1'),PC0:pin('GPIO_Output')});
   Object.assign(p.mcu.peripherals,{ADC1:{enabled:true},TIM3:{enabled:true,mode:'pwm',prescaler:15,period:999,pulse:500}});
   p.mcu=validateMcu({...p.mcu,coupleFiles:true});
   p.code=generateHal(p.mcu);
   assert.match(p.code,/#include "adc\.h"\n#include "i2c\.h"\n#include "tim\.h"\n#include "usart\.h"\n#include "gpio\.h"/);
   const result=await build(await prepareBuild({project:p,tools,root,target:'arm'}));
   assert.deepEqual(result.diagnostics.filter(d=>d.severity==='error'),[],board);
   const s=new FirmwareSession(p,{elf:new Uint8Array(await fs.readFile(result.elf))});
   for(let t=20;t<=400;t+=20)s.tick(t);
   // The example loop toggles the first output pin every 500 ms: high after the first pass.
   assert.equal(s.gpio.PC0?.value,3.3,`${board}: the loop runs after every MX_*_Init`);
   assert.match(s.buses.vcpOutput||'',/HAL ready/,board);
  }
 }finally{await fs.rm(root,{recursive:true,force:true});}
});
